bool Contact::step(int uiStepId)
{
	bool touching = stepContact();

	if (touching) {
		if (lastContactStep == -1) {
			Primitive::onNewTouch(getPrimitive(0), getPrimitive(1));
		}

		lastContactStep = uiStepId;
