	Tool::ToolState Tool::computeDesiredState()
	{
		RBXASSERT(Network::Players::backendProcessing(this, true));

		if (!getHandleConst())
			return NOTHING;

		if (!Workspace::contextInWorkspace(this))
			return HAS_HANDLE;

