		if (Humanoid::modelIsCharacter(getParent()))
		{
			Instance* parent = getParent();

			for (size_t i = 0; i < parent->numChildren(); i++)
			{
				if (dynamic_cast<Tool*>(parent->getChild(i)))
					total++;
			}
