		{
			if (getParent() == localPlayer->getPlayerBackpack())
			{
				moveAllToolsToBackpack(localPlayer);
				setParent(localPlayer->getCharacter());
			}
			else
			{
				setParent(localPlayer->getPlayerBackpack());
			}
		}

		RBXASSERT(getNumToolsInCharacter() < 2);
	}

