	void PartInstance::setFormFactorUi(FormFactor value)
	{
		if (partType != Part::BLOCK_PART)
			value = SYMETRIC;

		if (value != getFormFactor())
		{
			destroyJoints();

			setFormFactorXml(value);

			G3D::Vector3 uiSize = getPartSizeUi();
			uiSize.y = G3D::max<float>(1.0, G3D::iRound(uiSize.y));

