	bool MouseCommand::characterCanReach(const G3D::Vector3& hitPoint) const
	{
		PartInstance* head = Humanoid::getLocalHeadFromContext(workspace);

		if (head)
			return (head->getCoordinateFrame().translation - hitPoint).magnitude() < 60.0;
		else
			return false;
	}

