        return;
    }

    if (descriptor.type == Type::singleton<G3D::Color3>())
    {
        Color3Bridge::pushColor3(L, p.getValue<G3D::Color3>());
        return;
    }

    if (descriptor.type == Type::singleton<BrickColor>())
