		const G3D::CoordinateFrame& cframe = primitive->getCoordinateFrame();
		float transparency = 1.0f - alpha();

		return Part(partType, getPartSizeXml(), G3D::Color4(getColor3(), transparency), surfaces.surf6(), cframe);
	}

