#include "util/Sound.h"
#include "v8tree/Service.h"
namespace RBX {
class CameraVerb : public Verb { protected: Workspace* workspace; public: virtual void doIt(IDataState*); };
class FixedCameraCommand : public CameraVerb { public: virtual void doIt(IDataState*); };
template<class T> void StateStack<T>::clearStack() { clearStackAfter(-1); currentState=-1; }
void CameraVerb::doIt(IDataState* dataState) {
 ServiceProvider::create<Soundscape::SoundService>(workspace)->playSound(STEP_SOUND);
 dataState->clearStack(); dataState->setDirty(true);
}
void FixedCameraCommand::doIt(IDataState* dataState) {
 workspace->getCamera()->setCameraType(Camera::FIXED_CAMERA);
 dataState->clearStack(); dataState->setDirty(true);
}
}

namespace RBX {
class CameraModelViewCommand : public CameraVerb {public: virtual void doIt(IDataState*);};
const G3D::Rect2D& RootInstance::getViewPort() { return viewPort; }
void CameraModelViewCommand::doIt(IDataState* dataState) {
 workspace->setImageServerView(workspace->getViewPort());
 CameraVerb::doIt(dataState);
}
}

namespace RBX {
class CameraPanLeftCommand : public CameraVerb { public: virtual void doIt(IDataState*); };
void CameraPanLeftCommand::doIt(IDataState* dataState) {workspace->getCamera()->panUnits(-1); CameraVerb::doIt(dataState);}
class CameraPanRightCommand : public CameraVerb { public: virtual void doIt(IDataState*); };
void CameraPanRightCommand::doIt(IDataState* dataState) {workspace->getCamera()->panUnits(1); CameraVerb::doIt(dataState);}
class CameraTiltUpCommand : public CameraVerb { public: virtual void doIt(IDataState*); };
void CameraTiltUpCommand::doIt(IDataState* dataState) {if(workspace->getCamera()->tiltUnits(-1)) CameraVerb::doIt(dataState);}
class CameraTiltDownCommand : public CameraVerb { public: virtual void doIt(IDataState*); };
void CameraTiltDownCommand::doIt(IDataState* dataState) {if(workspace->getCamera()->tiltUnits(1)) CameraVerb::doIt(dataState);}
class CameraZoomInCommand : public CameraVerb { public: virtual void doIt(IDataState*); };
void CameraZoomInCommand::doIt(IDataState* dataState) {if(workspace->getCamera()->zoom(1.f)) CameraVerb::doIt(dataState);}
class CameraZoomOutCommand : public CameraVerb { public: virtual void doIt(IDataState*); };
void CameraZoomOutCommand::doIt(IDataState* dataState) {if(workspace->getCamera()->zoom(-1.f)) CameraVerb::doIt(dataState);}
class CameraZoomExtentsCommand : public CameraVerb { public: virtual void doIt(IDataState*); };
void CameraZoomExtentsCommand::doIt(IDataState* dataState) {workspace->getCamera()->zoomExtents(workspace->getViewPort()); CameraVerb::doIt(dataState);}
}

