{
	if (result != FMOD_OK) {
		std::string message = G3D::format("FMOD: %s", FMOD_ErrorString(result));
		RBX::StandardOut::singleton()->print(RBX::MESSAGE_WARNING, message.c_str());
		throw std::runtime_error(message);
	}
}

