	bool IMoving::checkSleep()
	{
		RBXASSERT(stepsToSleep > 0);

		if (stepsToSleep > 1)
		{
			stepsToSleep -= 1;
			return false;
		}

		RBXASSERT(stepsToSleep == 1);
		stepsToSleep = 0;
		onCanAggregateChanged(true);
		return true;
