		RBXASSERT(getWorldIfInWorkspace(context));

		Instance* parent = context->getParent();
		RBXASSERT(parent);

		Instance* parent2 = parent->getParent();
		RBXASSERT(parent2);

		while (parent2->getParent())
		{
			parent = parent2;
			parent2 = parent2->getParent();
