	void PartInstance::setPhysics(const G3D::CoordinateFrame& value)
	{
		if (value != getCoordinateFrame())
		{
			RBXASSERT(Math::isOrthonormal(value.rotation));
			primitive->setCoordinateFrame(value);
			PersistentPart.setDirty();
			onExtentsChanged();
		}
	}

