	void Workspace::insertItems(XmlElement* root, std::vector<boost::shared_ptr<Instance>>& instances, InsertMode insertMode, PromptMode promptMode)
	{
		RBXASSERT(instances.size() == 0);

		SerializerV2 serializer;
