//        { SiteList::Allow, L"http",  SITELOCK_INTRANET_ZONE },
//        { SiteList::Deny,  L"https", L"users.microsoft.com" },
//        { SiteList::Allow, L"https", L"microsoft.com"       },
//        { SiteList::Allow, L"https", SITELOCK_INTRANET_ZONE }};
// 
