	ContentProvider::~ContentProvider()
	{
		requestProcessor->join();
	}

	bool ContentProvider::isHttpUrl(const std::string& s)
	{
		if (s.find("http://") == 0)
			return true;

		if (s.find("https://") == 0)
			return true;

		return false;
	}

