	Camera::Camera()
		: Base(),
		  cameraFocus(G3D::Vector3(0, 0, -5)),
		  cameraType(FIXED_CAMERA),
		  animationType(AUTO),
		  cameraExternallyAdjusted(false)
	{
		setName("Camera");
		gCamera.setNearPlaneZ(-1.25);
		gCamera.setFarPlaneZ(-5000);
		gCamera.setFieldOfView(G3D::toRadians(60));

