	{
		float lastGoal;
		float currentGoal;
		float increment;
		bool latchToZero;
	public:
		float step(float goal)
		{
			if (latchToZero)
			{
				latchToZero = false;
				currentGoal = (currentGoal + goal) * 0.5f;
			}
			float result = currentGoal;
			currentGoal += increment;
