		float v1 = (currentGoal - rotation) * this->k;
		G3D::Vector3 v2 = normal * v1;

		((Body2008*)this->ref0->getBody())->accumulateTorque(-v2);
		((Body2008*)this->ref1->getBody())->accumulateTorque(v2);
	}
