G3D::Vector2 GuiRoot::toPixelSize(const G3D::Vector2& percent) {
 G3D::Vector2 pixelSize(0,0);
 if (canvasSize.y > 0.75f * canvasSize.x)
  pixelSize = (0.01f * percent) * G3D::Vector2(canvasSize.x, 0.75f * canvasSize.x);
