		boost::shared_ptr<const std::vector<boost::shared_ptr<Instance>>> c = instance->children.read();

		if (c)
		{
			for (std::vector<boost::shared_ptr<Instance>>::const_iterator iter = c->begin(); iter != c->end(); iter++)
