		World* world = Workspace::getWorldIfInWorkspace(this);
		if (world != myWorld)
		{
			RBXASSERT(myWorld || !roc_primitive_view()->getClump());

			if (myWorld)
			{
				setMovingManager(NULL);
				myWorld->removePrimitive(roc_primitive_view());
			}

			myWorld = world;

			if (world)
			{
				world->insertPrimitive(roc_primitive_view());
				setMovingManager(Workspace::getMyWorkspaceFast(this));
				roc_primitive_view()->setController(getTopPVController());
