			: notifier(notifier),
			  listener(listener)
		{
		}
	public:
		void operator()(Instance* instance)
		{
			notifier->Notifier<Instance, DescendentAdded>::raise(DescendentAdded(instance, instance->parent), listener);
			instance->for_eachChild(*this);
		}
	};

