	const Extents& Primitive::getFastFuzzyExtents() const
	{
		if (fuzzyExtentsStateId != roc_body_view()->getStateIndex())
		{
			fuzzyExtents = computeFuzzyExtents();
			fuzzyExtentsStateId = roc_body_view()->getStateIndex();
		}

		return fuzzyExtents;
	}

