	bool PartInstance::getLocked(Instance* instance)
	{
		PartInstance* thisPart = dynamic_cast<PartInstance*>(instance);

		if (thisPart)
		{
			return thisPart->locked;
		}
		else
		{
			for (size_t i = 0; i < instance->numChildren(); i++)
			{
				if (getLocked(instance->getChild(i)))
					return true;
			}
			return false;
		}
	}

