				return result;

			Server* owner = reinterpret_cast<Server*>(reinterpret_cast<char*>(static_cast<PluginInterface*>(this)) - 0x130);

			if (packet->data[0] == ID_NEW_INCOMING_CONNECTION)
			{
				try
