		void LevelBuilder::buildFace(NormalId normalId, Purpose purpose)
		{
			switch (normalId)
			{
			case NORM_X:
				buildRight(purpose);
				break;
			case NORM_Y:
				buildTop(purpose);
				break;
			case NORM_Z:
				buildBack(purpose);
				break;
			case NORM_X_NEG:
				buildLeft(purpose);
				break;
			case NORM_Y_NEG:
				buildBottom(purpose);
				break;
			case NORM_Z_NEG:
				buildFront(purpose);
				break;
