void RenderDevice::cleanup() {
    debugAssert(initialized());

    if (debugLog) {debugLog->println("Shutting down RenderDevice.");}

    if (debugLog) {debugLog->println("Restoring gamma.");}
    setGamma(1, 1);

    if (debugLog) {debugLog->println("Freeing all VAR memory");}

    if (deleteWindow) {
