    if (s != state.vertexAndPixelShader) {

        state.vertexAndPixelShader = s;

        if (s.notNull()) {
            alwaysAssertM(s->ok(), s->messages());
        }

        // The actual shader will change in beforePrimitive or when the arg list is bound.
    }
}


