    uint8*&             outData,
    int&                outLength) const {

    BinaryOutput out;

    encode(format, out);

    outData = (uint8*)System::malloc(out.size());
    debugAssert(outData);
    outLength = out.size();

    out.commit(outData);
}


void GImage::encode(
    Format              format,
    BinaryOutput&       out) const {

    switch (format) {
    case PPM_ASCII:
        encodePPMASCII(out);
        break;

    case PPM:
        encodePPM(out);
        break;

    case PNG:
        encodePNG(out);
        break;

    case JPEG:
        encodeJPEG(out);
        break;

    case BMP:
        encodeBMP(out);
        break;

    case TGA:
        encodeTGA(out);
        break;

    default:
        debugAssert(false);
    }
}

GImage GImage::insertRedAsAlpha(const GImage& alpha) const {
    debugAssert(alpha.width == width);
    debugAssert(alpha.height == height);

    GImage out(width, height, 4);

    for (int i = 0; i < width * height; ++i) {
        out.byte()[i * 4 + 0] = byte()[i * channels + 0];
        out.byte()[i * 4 + 1] = byte()[i * channels + 1];
        out.byte()[i * 4 + 2] = byte()[i * channels + 2];
        out.byte()[i * 4 + 3] = alpha.byte()[i * alpha.channels];
    }

    return out;
}


