            RECT wrect;
            GetWindowRect(window, &wrect);
            clientX = wrect.left;
            clientY = wrect.top;

            RECT rect = 
            {clientX + clientRectOffset.x, 
             clientY + clientRectOffset.y, 
             clientX + settings.width + clientRectOffset.x, 
