    clientRectOffset.x = oldLeft - rect.left;
    clientRectOffset.y = oldTop - rect.top;

	int total_width  = rect.right - rect.left;
	int total_height = rect.bottom - rect.top;

    int startX = 0;
    int startY = 0;

    if (! s.fullScreen) {
