                // Bottom triangle
                index[k + 0] = i + j * sq;
                index[k + 1] = i + (j + 1) * sq;
                index[k + 2] = (i + 1) + (j + 1) * sq;

                // Top triangle
                index[k + 3] = i + j * sq;
                index[k + 4] = (i + 1) + (j + 1) * sq;
