    std::vector<float> vertex(V * 3), normal(V * 3), texCoord(V * 2), color(V * 4);

    // Map V indices to a sq x sq grid
    for (int i = 0; i < sq; ++i) {
        for (int j = 0; j < sq; ++j) {

            int v = (i + j * sq) * 3;
            float x = (i / (float)sq - 0.5) * 2;
            float y = 0.5 - j / (float)sq;
            float a = x * 2 * 3.1415927;
            float r = ceil(cos(a * 10)) * 0.05 + 0.3; 
            vertex[v + 0] = -cos(a) * r;
            vertex[v + 1] = y;
