        case 1: ext = "bmp"; break;
        case 5: ext = "png"; break;
        case 2: ext = "tga"; break;
        case 4: ext = "ico"; break;
        case 3: ext = "pcx"; break;
        case 6: case 7: ext = "ppm"; break;
